      SUBROUTINE LCTABS (A)      CHARACTER A*(*)C      PARAMETER (IUC=65, IUCL=IUC+25, ILC=97, IDI=IUC-ILC)      CHARACTER TAB*1      DATA      TAB /'	'/C      IF (A .EQ. ' ') RETURNC      LENA = LEN(A)      IF (LENA .LE. 0) GO TO 10      DO I = 1, LENA        IF (A(I:I) .EQ. TAB) THEN          A(I:I) = ' '        ELSE IF (A(I:I) .NE. ' ') THEN          JUC = ICHAR(A(I:I))          IF ((JUC .GE. IUC) .AND. (JUC .LE. IUCL)) THEN            JLC = JUC - IDI            A(I:I) = CHAR(JLC)          ENDIF        ENDIF      END DO   10 RETURN      END